#!/usr/bin/env node
// Build script for Autodidact. It needs Node 18 or newer. It has no dependencies.
//
//   node scripts/build.mjs           write the generated files
//   node scripts/build.mjs --check   check the project. Exit code 1 if a generated file is old or a rule fails.
//
// manifest.json is the one list of subjects, chapters, and traces. This script writes from it:
//   index.html                          the main page (cards and counts)
//   assets/hub-data.js                  the data for the main search
//   subjects/<subject>/index.html       the page of each subject
// The trace pages (subjects/<subject>/<trace>.html) are written by hand. This script only checks them.

import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const CHECK = process.argv.includes('--check');
const manifest = JSON.parse(readFileSync(join(ROOT, 'manifest.json'), 'utf8'));

// Trace pages that have no COMPLEXITY yet. Remove a file from scripts/complexity-pending.json when you add it.
// When the list is empty, every trace page must have COMPLEXITY.
const pending = new Set(JSON.parse(readFileSync(join(ROOT, 'scripts', 'complexity-pending.json'), 'utf8')));

const errors = [];
const fail = (msg) => errors.push(msg);

// ---------- helpers ----------
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
const traceCount = (n) => (n === 0 ? 'No traces yet' : plural(n, 'trace', 'traces'));
const GENERATED = '<!-- Generated by scripts/build.mjs from manifest.json. Do not edit this file by hand. -->';

function head(title, cssHref, assetsPrefix) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="color-scheme" content="light dark">
${GENERATED}
<title>${esc(title)}</title>
<link rel="icon" href="${assetsPrefix}assets/favicon.ico" sizes="32x32">
<link rel="icon" href="${assetsPrefix}assets/favicon.svg" type="image/svg+xml">
<link rel="apple-touch-icon" href="${assetsPrefix}assets/apple-touch-icon.png">
<link rel="stylesheet" href="${assetsPrefix}assets/base.css">
<link rel="stylesheet" href="${assetsPrefix}assets/theme.css">
<link rel="stylesheet" href="${assetsPrefix}assets/${cssHref}">
<script src="${assetsPrefix}assets/theme.js"></script>
</head>
`;
}

// The search bar. assets/search.js makes it work. The results panel floats under the bar.
const searchBox = (placeholder) => `  <div class="spot" role="search">
    <div class="spotbar">
      <svg viewBox="0 0 20 20" aria-hidden="true"><circle cx="8.5" cy="8.5" r="5.5" fill="none" stroke="currentColor" stroke-width="1.8"/><path d="M12.8 12.8 L17.5 17.5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>
      <input id="q" type="text" role="combobox" aria-label="Search" aria-autocomplete="list" aria-expanded="false" aria-controls="resultlist" autocomplete="off" autocapitalize="off" spellcheck="false" enterkeyhint="go" placeholder="${esc(placeholder)}">
      <kbd class="hint" id="hint" aria-hidden="true">/</kbd>
      <button type="button" class="clear" id="clear" hidden>Clear</button>
    </div>
    <div class="panel" id="results" hidden>
      <p class="stat" id="stat" aria-live="polite"></p>
      <ul class="hits" id="resultlist" role="listbox" aria-label="Search results"></ul>
      <p class="none" id="none" hidden></p>
      <div class="panelfoot" aria-hidden="true"><span><kbd>↑</kbd><kbd>↓</kbd> move</span><span><kbd>↵</kbd> open</span><span><kbd>esc</kbd> clear</span></div>
    </div>
  </div>
`;

const SCRIPTS = (prefix) => `<script src="${prefix}assets/fuzzy.js"></script>
<script src="${prefix}assets/hub-data.js"></script>
<script src="${prefix}assets/search.js"></script>
`;

// ---------- validation ----------
const subjectsById = new Map();
const divisionsById = new Map(manifest.divisions.map((d) => [d.id, d]));
for (const s of manifest.subjects) {
  if (subjectsById.has(s.id)) fail(`Subject id "${s.id}" is used two times.`);
  subjectsById.set(s.id, s);
  if (!divisionsById.has(s.division)) fail(`Subject "${s.id}" uses the unknown division "${s.division}".`);
  const chapters = s.chapters || [];
  const numbers = new Set(chapters.map((c) => c.number));
  if (numbers.size !== chapters.length) fail(`Subject "${s.id}" has two chapters with the same number.`);
  const files = new Set();
  for (const t of s.traces || []) {
    if (files.has(t.file)) fail(`Trace file "${t.file}" is listed two times in "${s.id}".`);
    files.add(t.file);
    if (chapters.length && !numbers.has(t.chapter)) fail(`Trace "${t.file}" uses the unknown chapter ${t.chapter}.`);
    if (!chapters.length && t.chapter !== undefined) fail(`Trace "${t.file}" has a chapter, but "${s.id}" has none.`);
    for (const key of ['name', 'description', 'keywords']) if (!t[key]) fail(`Trace "${t.file}" has no ${key}.`);
    if (!Array.isArray(t.tags) || !t.tags.length) fail(`Trace "${t.file}" has no tags.`);
    const p = join(ROOT, 'subjects', s.id, t.file);
    if (!existsSync(p)) { fail(`Trace file is missing: subjects/${s.id}/${t.file}`); continue; }
    const html = readFileSync(p, 'utf8');
    const where = `subjects/${s.id}/${t.file}`;
    for (const need of ['assets/base.css', 'assets/theme.css', 'assets/trace.css', 'assets/theme.js', 'assets/player.js']) {
      if (!html.includes(need)) fail(`${where} does not load ${need}.`);
    }
    for (const icon of ['assets/favicon.ico', 'assets/favicon.svg', 'assets/apple-touch-icon.png']) {
      if (!html.includes(icon)) fail(`${where} does not link ${icon}. Copy the three icon <link> lines from another trace page into the <head>.`);
    }
    if (/fonts\.googleapis\.com|fonts\.gstatic\.com/.test(html)) fail(`${where} loads fonts from the network. Use assets/base.css.`);
    if (!html.includes('//SIM-START') || !html.includes('//SIM-END')) fail(`${where} has no //SIM-START and //SIM-END markers.`);
    if (!html.includes('window.TRACE') && !/var TRACE\s*=/.test(html)) fail(`${where} does not define TRACE.`);
    const hasCx = html.includes('//COMPLEXITY-START') && html.includes('//COMPLEXITY-END') && /var COMPLEXITY\s*=/.test(html);
    if (pending.has(t.file)) {
      if (hasCx) fail(`${where} has COMPLEXITY. Remove "${t.file}" from scripts/complexity-pending.json.`);
    } else if (!hasCx) {
      fail(`${where} has no COMPLEXITY. Put "var COMPLEXITY = {...}" between //COMPLEXITY-START and //COMPLEXITY-END, after //SIM-END. The fields are in README.md.`);
    }
  }
  const dir = join(ROOT, 'subjects', s.id);
  if (!existsSync(dir)) fail(`Subject folder is missing: subjects/${s.id}`);
  else {
    for (const f of readdirSync(dir)) {
      if (f.endsWith('.html') && f !== 'index.html' && !files.has(f)) fail(`subjects/${s.id}/${f} is not in manifest.json.`);
    }
  }
}
for (const f of pending) {
  if (!manifest.subjects.some((s) => s.traces.some((t) => t.file === f))) fail(`scripts/complexity-pending.json lists "${f}", which is not in manifest.json.`);
}
for (const d of manifest.divisions) {
  if (!manifest.subjects.some((s) => s.division === d.id)) fail(`Division "${d.id}" has no subject.`);
}
if (existsSync(join(ROOT, 'subjects'))) {
  for (const f of readdirSync(join(ROOT, 'subjects'), { withFileTypes: true })) {
    if (f.isDirectory() && !subjectsById.has(f.name)) fail(`Folder subjects/${f.name} is not in manifest.json.`);
  }
}

// ---------- generated files ----------
const out = new Map(); // path -> text

// Main page
{
  const total = manifest.subjects.reduce((n, s) => n + s.traces.length, 0);
  let groups = '';
  for (const d of manifest.divisions) {
    const subs = manifest.subjects.filter((s) => s.division === d.id);
    groups += `  <section class="group">
    <h2><span>${esc(d.name)}</span><span>${plural(subs.length, 'subject', 'subjects')}</span></h2>
    <ul class="grid" style="--cols:${d.columns}">
`;
    for (const s of subs) {
      groups += `      <li><a class="card" href="subjects/${s.id}/index.html">
        <p class="name">${esc(s.name)}</p>
        <p class="desc">${esc(s.description)}</p>
        <div class="foot"><span>${traceCount(s.traces.length)}</span><span class="go">Open →</span></div>
      </a></li>
`;
    }
    groups += `    </ul>
  </section>
`;
  }
  out.set('index.html', `${head(manifest.site.title, 'hub.css', '')}<body data-root="" data-autofocus>
<div class="wrap wide">
  <header class="hero">
    <h1>${esc(manifest.site.title)}</h1>
    <p>${esc(manifest.site.intro)}</p>
  </header>

${searchBox(manifest.site.searchPlaceholder)}
  <div id="groups" class="sections">
${groups}  </div>
</div>
${SCRIPTS('')}</body>
</html>
`);
  out.set('assets/hub-data.js', `// Generated by scripts/build.mjs from manifest.json. Do not edit this file by hand.
// ${manifest.subjects.length} subjects and ${total} traces.
window.HUB_DATA = ${JSON.stringify(buildData(), null, 1)};
`);
}

function buildData() {
  const data = [];
  for (const s of manifest.subjects) {
    data.push({ type: 'subject', name: s.name, desc: s.description, tags: [divisionsById.get(s.division).name], kw: s.keywords, subjectName: s.name, subjectId: s.id, href: `subjects/${s.id}/index.html` });
  }
  for (const s of manifest.subjects) {
    for (const t of orderedTraces(s)) {
      data.push({ type: 'trace', name: t.name, desc: t.description, tags: t.tags, kw: t.keywords, subjectName: s.name, subjectId: s.id, href: `subjects/${s.id}/${t.file}` });
    }
  }
  return data;
}

function orderedTraces(s) {
  const chapters = s.chapters || [];
  if (!chapters.length) return s.traces;
  return chapters.flatMap((c) => s.traces.filter((t) => t.chapter === c.number));
}

// Subject pages
for (const s of manifest.subjects) {
  const division = divisionsById.get(s.division);
  const row = (t) => `      <li data-kw="${esc(t.keywords)}"><a class="row" href="${esc(t.file)}">
        <div class="main">
          <p class="name">${esc(t.name)}</p>
          <p class="desc">${esc(t.description)}</p>
        </div>
        <div class="tags">${t.tags.map((g) => `<span class="tag">${esc(g)}</span>`).join('')}</div>
        <span class="go">Open trace →</span>
      </a></li>
`;
  const top = `<body data-root="../../" data-subject="${s.id}">
<div class="wrap">
  <a class="back" href="../../index.html">← ${esc(manifest.site.title)}</a>
  <header>
    <p class="eyebrow">${esc(division.name)}</p>
    <h1 id="subj">${esc(s.name)}</h1>
    <p>${esc(s.description)}</p>
  </header>

${searchBox('Search all subjects and topics')}
`;
  let sections;
  if (!s.traces.length) {
    sections = `  <div id="chapters" class="sections">
  <section class="group">
    <h2><span>Animated traces</span><span>No traces yet</span></h2>
    <p class="empty">No animated traces here yet.</p>
  </section>
  </div>
`;
  } else {
    let chapters = '';
    for (const c of s.chapters || [{ number: 0, title: 'Animated traces' }]) {
      const list = s.traces.filter((t) => (s.chapters ? t.chapter === c.number : true));
      const title = s.chapters ? `Chapter ${c.number} · ${c.title}` : c.title;
      chapters += `  <section class="group">
    <h2><span>${esc(title)}</span><span>${traceCount(list.length)}</span></h2>
${list.length ? `    <ul class="rows"${s.chapters ? ` data-chapter="${c.number}"` : ''}>
${list.map(row).join('')}    </ul>
` : `    <p class="empty">No traces in this chapter yet.</p>
`}  </section>
`;
    }
    sections = `  <div id="chapters" class="sections">
${chapters}  </div>
`;
  }
  const page = `${top}${sections}</div>
${SCRIPTS('../../')}</body>
</html>
`;
  out.set(`subjects/${s.id}/index.html`, head(s.name, 'hub.css', '../../') + page);
}

// ---------- write or check ----------
const stale = [];
for (const [rel, text] of out) {
  const p = join(ROOT, rel);
  const current = existsSync(p) ? readFileSync(p, 'utf8') : null;
  if (current === text) continue;
  if (CHECK) stale.push(rel);
  else { mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, text); console.log('wrote', rel); }
}
if (CHECK && stale.length) fail(`These generated files are old. Run "node scripts/build.mjs":\n  ${stale.join('\n  ')}`);

if (errors.length) {
  console.error(`\n${errors.length} problem${errors.length === 1 ? '' : 's'}:`);
  for (const e of errors) console.error(' - ' + e);
  process.exit(1);
}
console.log(CHECK ? 'Check passed.' : `Done. ${out.size} generated files are up to date.`);
